def decide(recipient_reputation, round_num, my_history):
    # Use own history to adjust cooperation threshold
    coop_count = 0
    for round_data in my_history:
        if round_data['action'] == 'cooperate':
            coop_count += 1
    total_rounds = len(my_history)
    coop_rate = coop_count / total_rounds if total_rounds > 0 else 0.5

    # Lower threshold if we have been less cooperative in the past (to encourage cooperation)
    threshold = 0.5 if coop_rate > 0.5 else 0.3
    return recipient_reputation > threshold

