def decide(recipient_reputation, round_num, my_history):
    # Cooperate only if we have a good reputation score and we haven't
    # cooperated too often relative to total actions.
    # Lower the reputation threshold and relax the personal history condition.
    if round_num > 3 and recipient_reputation > 0.5:
        my_coops = sum(1 for a in my_history if a)  # True means cooperate
        my_total = len(my_history)
        # Only cooperate if cooperations are at most one third of all actions.
        if my_total == 0 or my_coops <= my_total // 3:
            return True
    return False
